 
// Latin-subset brand fonts embedded as base64 so the PDF renderer (headless
// Chromium, which has no brand fonts installed) uses the real Source Serif 4 /
// Source Sans 3 / IBM Plex Mono. Regenerate from @fontsource woff2 if changed.
export const EMBEDDED_FONTS_CSS = `
@font-face{font-family:"Source Serif 4";font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format("woff2");}
@font-face{font-family:"Source Serif 4";font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format("woff2");}
@font-face{font-family:"Source Sans 3";font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format("woff2");}
@font-face{font-family:"Source Sans 3";font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format("woff2");}
@font-face{font-family:"IBM Plex Mono";font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format("woff2");}
@font-face{font-family:"IBM Plex Mono";font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format("woff2");}
`;
